import { useState } from "react";

function Hop() {
  const [mau, setMau] = useState("white");
  return (
    <div
      onMouseOver={() => setMau("yellow")}
      onMouseOut={() => setMau("white")}
      style={{ background: mau, padding: 20 }}
    >
      Di chuot vao day
    </div>
  );
}

export default Hop;
